package com.hbm.machine.reactor.rbmk.failure;
import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.Level;import net.neoforged.bus.api.IEventBus;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** Typed delivery for the genuine radialDigamma and rbmkflame source effects after removing sided-proxy globals. */
public final class RbmkFailureEffects {
 public record Packet(boolean flame,double x,double y,double z,int amount)implements CustomPacketPayload{public static final Type<Packet> TYPE=new Type<>(ResourceLocation.parse("hbm:rbmk_failure_effects"));public static final StreamCodec<RegistryFriendlyByteBuf,Packet> CODEC=StreamCodec.of((b,p)->{b.writeBoolean(p.flame);b.writeDouble(p.x);b.writeDouble(p.y);b.writeDouble(p.z);b.writeInt(p.amount);},b->new Packet(b.readBoolean(),b.readDouble(),b.readDouble(),b.readDouble(),b.readInt()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
 public static void register(IEventBus bus){bus.addListener((RegisterPayloadHandlersEvent event)->event.registrar("1").playToClient(Packet.TYPE,Packet.CODEC,(packet,context)->context.enqueueWork(()->com.hbm.client.reactor.rbmk.failure.RbmkFailureClient.receive(packet))));}
 public static void radial(Level world,double x,double y,double z,int count){send(world,new Packet(false,x,y,z,count),1000);}public static void flame(Level world,double x,double y,double z,int lifetime){send(world,new Packet(true,x,y,z,lifetime),75);}private static void send(Level level,Packet packet,int range){if(level instanceof ServerLevel world){for(var player:world.players())if(player.distanceToSqr(packet.x,packet.y,packet.z)<range*range)PacketDistributor.sendToPlayer(player,packet);}else com.hbm.client.reactor.rbmk.failure.RbmkFailureClient.receive(packet);}private RbmkFailureEffects(){}
}
